use super::*;
use std::{io::{Read, Write}, path::PathBuf, sync::atomic::AtomicU64};
fn root() -> PathBuf { static NEXT:AtomicU64=AtomicU64::new(0);let p=std::env::temp_dir().join(format!("fileid-independent-request-{}-{}",std::process::id(),NEXT.fetch_add(1,Ordering::Relaxed)));std::fs::create_dir(&p).unwrap();std::fs::write(p.join("image.png"),[0x89,b'P',b'N',b'G']).unwrap();println!("Generated independent request state retained: {}",p.display());p }
fn flag() -> Arc<AtomicBool> {Arc::new(AtomicBool::new(false))}
fn snapshot(s:&ResourceScheduler)->(u64,usize,usize,usize) {let v=s.snapshot();(v.memory_mb,v.cpu,v.io,v.active)}
fn request(stream:&mut std::net::TcpStream) {stream.set_read_timeout(Some(Duration::from_secs(5))).unwrap();let mut bytes=Vec::new();loop {let mut buf=[0;4096];let n=stream.read(&mut buf).unwrap();assert!(n>0);bytes.extend_from_slice(&buf[..n]);assert!(bytes.len()<65536);if let Some(end)=bytes.windows(4).position(|x|x==b"\r\n\r\n") {let headers=String::from_utf8_lossy(&bytes[..end]);let size:usize=headers.lines().find_map(|line|line.to_ascii_lowercase().strip_prefix("content-length:").map(|v|v.trim().parse().unwrap())).unwrap();if bytes.len()>=end+4+size {assert!(headers.contains("Bearer generated-auth"));return;}}}}
fn reply(stream:&mut std::net::TcpStream) {let body=r#"{"choices":[{"message":{"content":"generated independent response, not inference"}}]}"#;write!(stream,"HTTP/1.1 200 OK\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}",body.len()).unwrap();}
async fn fixture(root:&Path)->(Arc<VlmServer>,Arc<ProcessTracker>,Arc<ResourceScheduler>,std::net::TcpListener) {let listener=std::net::TcpListener::bind((std::net::Ipv4Addr::LOCALHOST,0)).unwrap();let url=format!("http://{}",listener.local_addr().unwrap());let s=ResourceScheduler::new(||(16384,12000),1,1);let lease=reserve_host(s.clone(),Demand{memory_mb:64,cpu:1,io:1},flag()).await.unwrap();let marker=root.join("own-child-ready");let mut cmd=Command::new(std::env::current_exe().unwrap());cmd.args(["--exact","models::vlm_server::request_cancel_tests::generated_independent_request_child","--ignored","--nocapture"]).env("FILEID_INDEPENDENT_REQUEST_READY",&marker).stdin(Stdio::null()).stdout(Stdio::null()).stderr(Stdio::null());let tracker=Arc::new(ProcessTracker::default());let process=OwnedProcess::spawn(&mut cmd,Some(lease.clone()),&tracker).unwrap();tokio::time::timeout(Duration::from_secs(5),async {while !marker.exists() {tokio::task::yield_now().await;}}).await.unwrap();lease.retain_memory();let server=Arc::new(VlmServer {last_timings:parking_lot::Mutex::new(None),process,base_url:url,api_key:"generated-auth".into(),client:build_loopback_client().unwrap(),scheduler:s.clone(),cancel:flag(),request_gate:tokio::sync::Mutex::new(())});(server,tracker,s,listener)}
async fn finish(server:Arc<VlmServer>,tracker:&ProcessTracker,s:&ResourceScheduler) {Arc::try_unwrap(server).ok().unwrap().shutdown().await.unwrap();tracker.shutdown().await.unwrap();assert_eq!(snapshot(s),(0,0,0,0));}
fn receipt(root:&Path,value:serde_json::Value) {std::fs::write(root.join("receipt.json"),serde_json::to_vec(&value).unwrap()).unwrap();}
fn normal(listener:std::net::TcpListener)->std::thread::JoinHandle<()> {std::thread::spawn(move || {let(mut stream,_)=listener.accept().unwrap();request(&mut stream);reply(&mut stream);})}
fn held(listener:std::net::TcpListener)->(tokio::sync::oneshot::Receiver<()>,std::sync::mpsc::Sender<bool>,std::thread::JoinHandle<()>) {let(ready,rx)=tokio::sync::oneshot::channel();let(tx,release)=std::sync::mpsc::channel();let worker=std::thread::spawn(move || {let(mut stream,_)=listener.accept().unwrap();request(&mut stream);ready.send(()).unwrap();if release.recv_timeout(Duration::from_secs(5)).unwrap() {reply(&mut stream);}});(rx,tx,worker)}
#[tokio::test]
#[ignore="own executable child only, not inference runtime"]
async fn generated_independent_request_child() {std::fs::write(std::env::var_os("FILEID_INDEPENDENT_REQUEST_READY").unwrap(),std::process::id().to_string()).unwrap();tokio::time::sleep(Duration::from_secs(60)).await;}
#[tokio::test]
async fn independent_request_precancel_preserves_idle_native_for_next_request() {
    let root=root();let(server,tracker,s,listener)=fixture(&root).await;let cancelled=Arc::new(AtomicBool::new(true));let error=server.complete_with_cancel(&root.join("image.png"),"generated",1,cancelled).await.unwrap_err();assert!(error.downcast_ref::<HostAdmissionError>().is_some());assert_eq!(snapshot(&s),(64,0,0,1));assert!(!server.cancel.load(Ordering::Relaxed));let worker=normal(listener);server.complete_with_cancel(&root.join("image.png"),"generated",1,flag()).await.unwrap();worker.join().unwrap();assert!(server.process.poll_exit().unwrap().is_none());receipt(&root,serde_json::json!({"precancelledRequestOnly":true,"healthyNextRequest":true}));finish(server,&tracker,&s).await;
}
#[tokio::test]
async fn independent_request_waiting_turn_cancel_does_not_cancel_other_request() {
    let root=root();let(server,tracker,s,listener)=fixture(&root).await;let(ready,release,worker)=held(listener);let a=server.clone();let image=root.join("image.png");let first=tokio::spawn(async move {a.complete_with_cancel(&image,"first",1,flag()).await});ready.await.unwrap();let cancelled=flag();let a=server.clone();let image=root.join("image.png");let c=cancelled.clone();let second=tokio::spawn(async move {a.complete_with_cancel(&image,"waiting",1,c).await});tokio::task::yield_now().await;cancelled.store(true,Ordering::Relaxed);let error=tokio::time::timeout(Duration::from_secs(5),second).await.unwrap().unwrap().unwrap_err();assert!(error.downcast_ref::<HostAdmissionError>().is_some());assert_eq!(snapshot(&s),(576,1,1,2));assert!(!server.cancel.load(Ordering::Relaxed));release.send(true).unwrap();first.await.unwrap().unwrap();worker.join().unwrap();assert_eq!(snapshot(&s),(64,0,0,1));receipt(&root,serde_json::json!({"waitingRequestCancelled":true,"otherRequestSucceeded":true,"singleWorkCharge":true}));finish(server,&tracker,&s).await;
}
async fn queued(server:&Arc<VlmServer>,root:&Path,s:&ResourceScheduler,stop:bool) {
    let blocker=reserve_host(server.scheduler.clone(),Demand{memory_mb:8,cpu:1,io:1},flag()).await.unwrap();let cancel=flag();let a=server.clone();let image=root.join("image.png");let c=cancel.clone();let request=tokio::spawn(async move {a.complete_with_cancel(&image,"queued",1,c).await});tokio::time::timeout(Duration::from_secs(5),async {while s.snapshot().waiting!=1 {tokio::task::yield_now().await;}}).await.unwrap();if stop {server.cancel.store(true,Ordering::Relaxed);}else {cancel.store(true,Ordering::Relaxed);}let error=tokio::time::timeout(Duration::from_secs(5),request).await.unwrap().unwrap().unwrap_err();assert!(error.downcast_ref::<HostAdmissionError>().is_some());assert_eq!(s.snapshot().waiting,0);assert_eq!(snapshot(s),(72,1,1,2));assert!(server.process.poll_exit().unwrap().is_none());drop(blocker);
}
#[tokio::test]
async fn independent_request_queued_cancel_does_not_poison_server_lifetime() {
    let root=root();let(server,tracker,s,listener)=fixture(&root).await;queued(&server,&root,&s,false).await;assert!(!server.cancel.load(Ordering::Relaxed));let worker=normal(listener);server.complete_with_cancel(&root.join("image.png"),"next",1,flag()).await.unwrap();worker.join().unwrap();receipt(&root,serde_json::json!({"queuedRequestCancelled":true,"healthyNextRequest":true,"noQueuedHttp":true}));finish(server,&tracker,&s).await;
}
#[tokio::test]
async fn independent_request_lifetime_stop_also_cancels_queued_admission() {
    let root=root();let(server,tracker,s,listener)=fixture(&root).await;queued(&server,&root,&s,true).await;listener.set_nonblocking(true).unwrap();assert!(listener.accept().is_err());receipt(&root,serde_json::json!({"lifetimeStopCancelsWait":true,"noHttpDispatched":true}));finish(server,&tracker,&s).await;
}
#[tokio::test]
async fn independent_request_dispatched_cancel_returns_only_after_confirmed_reap() {
    let root=root();let(server,tracker,s,listener)=fixture(&root).await;let(ready,release,worker)=held(listener);let cancel=flag();let c=cancel.clone();let a=server.clone();let image=root.join("image.png");let request=tokio::spawn(async move {a.complete_with_cancel(&image,"active",1,c).await});ready.await.unwrap();assert_eq!(snapshot(&s),(576,1,1,2));cancel.store(true,Ordering::Relaxed);let error=tokio::time::timeout(Duration::from_secs(7),request).await.unwrap().unwrap().unwrap_err();assert!(error.downcast_ref::<HostAdmissionError>().is_some());assert!(server.process.poll_exit().unwrap().is_some());assert_eq!(snapshot(&s),(0,0,0,0));assert!(tracker.allows_fallback());assert!(!server.cancel.load(Ordering::Relaxed));release.send(false).unwrap();worker.join().unwrap();receipt(&root,serde_json::json!({"activeRequestCancelled":true,"returnAfterReap":true,"hostAndNativeResourcesEnded":true,"vendorRuntime":false}));finish(server,&tracker,&s).await;
}
#[cfg(unix)]
#[tokio::test]
async fn independent_request_predispatch_fifo_cancel_preserves_native_and_live_reader_charge() {
    use std::os::{unix::ffi::OsStrExt,fd::FromRawFd};let root=root();let(server,tracker,s,listener)=fixture(&root).await;let fifo=root.join("blocked-image.fifo");let name=std::ffi::CString::new(fifo.as_os_str().as_bytes()).unwrap();assert_eq!(unsafe{libc::mkfifo(name.as_ptr(),0o600)},0);let cancel=flag();let c=cancel.clone();let a=server.clone();let image=fifo.clone();let request=tokio::spawn(async move {a.complete_with_cancel(&image,"before dispatch",1,c).await});let writer=tokio::time::timeout(Duration::from_secs(5),async {loop {let fd=unsafe{libc::open(name.as_ptr(),libc::O_WRONLY|libc::O_NONBLOCK)};if fd>=0 {break unsafe{std::fs::File::from_raw_fd(fd)};}assert_eq!(std::io::Error::last_os_error().raw_os_error(),Some(libc::ENXIO));tokio::task::yield_now().await;}}).await.unwrap();assert_eq!(snapshot(&s),(576,1,1,2));cancel.store(true,Ordering::Relaxed);let error=tokio::time::timeout(Duration::from_secs(5),request).await.unwrap().unwrap().unwrap_err();assert!(error.downcast_ref::<HostAdmissionError>().is_some());assert!(server.process.poll_exit().unwrap().is_none());assert_eq!(snapshot(&s),(576,1,1,2));drop(writer);tokio::time::timeout(Duration::from_secs(5),async {while snapshot(&s)!=(64,0,0,1) {tokio::task::yield_now().await;}}).await.unwrap();let worker=normal(listener);server.complete_with_cancel(&root.join("image.png"),"next",1,flag()).await.unwrap();worker.join().unwrap();receipt(&root,serde_json::json!({"predispatchCancelKeptNative":true,"liveBlockingReadHeld512MiB":true,"healthyNextRequest":true}));finish(server,&tracker,&s).await;
}
#[tokio::test]
async fn independent_request_abandoned_dispatch_is_retained_by_shared_shutdown() {
    let root=root();let(server,tracker,s,listener)=fixture(&root).await;let(ready,release,worker)=held(listener);let a=server.clone();let image=root.join("image.png");let request=tokio::spawn(async move {a.complete_with_cancel(&image,"abandoned",1,flag()).await});ready.await.unwrap();request.abort();assert!(request.await.unwrap_err().is_cancelled());tracker.shutdown().await.unwrap();assert!(server.process.poll_exit().unwrap().is_some());assert_eq!(snapshot(&s),(0,0,0,0));release.send(false).unwrap();worker.join().unwrap();receipt(&root,serde_json::json!({"abandonedRequestStoppedNative":true,"sharedShutdownConfirmedReap":true}));finish(server,&tracker,&s).await;
}
#[test]
fn independent_request_actual_startup_and_pipeline_do_not_retain_old_job_cancel_or_outer_race() {
    let source=include_str!("vlm_server.rs");assert!(source.contains("cancel: Arc::new(AtomicBool::new(false))"));assert!(source.contains("move || stop.load(Ordering::Relaxed) || request.load(Ordering::Relaxed)"));assert!(source.contains("if cancelled && native_incomplete"));assert!(source.contains("self.process.stop_and_wait().await"));let pipeline=include_str!("../pipeline/deep_analyze.rs");let start=pipeline.find("async fn complete_cancellable(").unwrap();let end=pipeline[start..].find("/// Analyze one file").unwrap()+start;assert!(!pipeline[start..end].contains("tokio::select!"));assert!(pipeline[start..end].contains("complete_with_cancel"));assert!(pipeline.contains("server.complete_with_cancel(&test_img"));let command=include_str!("../commands/deep_analyze.rs");assert!(command.contains("vlm_server_payload_ok(&s, &cancel).await"));assert!(command.contains("vlm_server_payload_ok(srv, &cancel).await"));
}
